CREATE SCHEMA IF NOT EXISTS fbads;
SET search_path TO fbads;
CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE IF NOT EXISTS icp_profiles (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', age_min integer NOT NULL DEFAULT 25, age_max integer NOT NULL DEFAULT 55, genders text NOT NULL DEFAULT 'all', geo text NOT NULL DEFAULT 'US', interests text NOT NULL DEFAULT '', pain_points text NOT NULL DEFAULT '', tone text NOT NULL DEFAULT 'confident, direct', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS briefs (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, icp_id integer REFERENCES icp_profiles(id), product text NOT NULL, offer text DEFAULT '', angle text DEFAULT '', landing_url text DEFAULT '', formats text NOT NULL DEFAULT 'feed_square,story_vertical', media_types text NOT NULL DEFAULT 'image', variant_count integer NOT NULL DEFAULT 2, notes text DEFAULT '', status text NOT NULL DEFAULT 'generating', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS creatives (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, brief_id integer REFERENCES briefs(id), media_type text NOT NULL, format text NOT NULL, asset_path text, asset_url text, primary_text text, headline text, description text, cta text DEFAULT 'LEARN_MORE', hook text, status text NOT NULL DEFAULT 'generated', fb_image_hash text, fb_video_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, objective text NOT NULL DEFAULT 'OUTCOME_TRAFFIC', status text NOT NULL DEFAULT 'draft', daily_budget_cents integer NOT NULL DEFAULT 1500, icp_id integer REFERENCES icp_profiles(id), fb_campaign_id text, launched_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ad_sets (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, campaign_id integer REFERENCES campaigns(id), name text NOT NULL DEFAULT '', fb_adset_id text, targeting_json jsonb, daily_budget_cents integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ads (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ad_set_id integer REFERENCES ad_sets(id), creative_id integer REFERENCES creatives(id), name text NOT NULL DEFAULT '', fb_ad_id text, fb_creative_id text, fb_preview_html text, status text NOT NULL DEFAULT 'paused', engine_managed integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS metrics_daily (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ad_id integer REFERENCES ads(id), date date NOT NULL, impressions integer DEFAULT 0, reach integer DEFAULT 0, frequency double precision DEFAULT 0, clicks integer DEFAULT 0, ctr double precision DEFAULT 0, cpc_cents integer DEFAULT 0, cpm_cents integer DEFAULT 0, spend_cents integer DEFAULT 0, conversions integer DEFAULT 0, cpa_cents integer DEFAULT 0, roas double precision DEFAULT 0, synced_at timestamptz NOT NULL DEFAULT now(), UNIQUE(ad_id,date));
CREATE TABLE IF NOT EXISTS jobs (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'pending', result jsonb, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE IF NOT EXISTS engine_actions (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ad_id integer REFERENCES ads(id), campaign_id integer REFERENCES campaigns(id), action text NOT NULL, reason text NOT NULL, metrics_snapshot jsonb NOT NULL DEFAULT '{}', executed integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS competitor_ads (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, query text NOT NULL, page_name text NOT NULL, library_id text NOT NULL UNIQUE, body text, headline text, cta text, media_type text, media_url text, snapshot_url text, started_at date, platforms text, analysis text, starred integer NOT NULL DEFAULT 0, collected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS learnings (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, dimension text NOT NULL, insight text NOT NULL, evidence text, confidence double precision NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
